DROP TABLE IF EXISTS `casehistorymbgl`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `casehistorymbgl` (
  `mbbm` varchar(255) NOT NULL COMMENT '模板编码',
  `company_id` varchar(32) NOT NULL COMMENT '租户号',
  `mbmc` varchar(255) NOT NULL COMMENT '模板名称',
  `mblx` varchar(255) NOT NULL COMMENT '模板类型;(0：通用，1：个人)',
  `bllx` varchar(255) NOT NULL COMMENT '病历类型;(0：西医病历，1：中医病历)',
  `zs` varchar(255) DEFAULT NULL COMMENT '主诉',
  `grs` varchar(255) DEFAULT NULL COMMENT '个人史',
  `gms` varchar(255) DEFAULT NULL COMMENT '过敏史',
  `jbs` varchar(255) DEFAULT NULL COMMENT '疾病史',
  `crbs` varchar(255) DEFAULT NULL COMMENT '传染病史',
  `sss` varchar(255) DEFAULT NULL COMMENT '手术史',
  `sxs` varchar(255) DEFAULT NULL COMMENT '输血史',
  `tgjc` varchar(255) DEFAULT NULL COMMENT '体格检查',
  `jzzd` varchar(255) DEFAULT NULL COMMENT '急诊诊断',
  `jzxg` varchar(255) DEFAULT NULL COMMENT '急诊效果',
  `jzs` varchar(255) DEFAULT NULL COMMENT '家族史',
  `yjz` varchar(255) DEFAULT NULL COMMENT '月经史',
  `hys` varchar(255) DEFAULT NULL COMMENT '婚育史',
  `fzjc` varchar(255) DEFAULT NULL COMMENT '辅助检查',
  `xbs` varchar(255) DEFAULT NULL COMMENT '现病史',
  `jws` varchar(255) DEFAULT NULL COMMENT '既往史',
  `lxbxs` varchar(255) DEFAULT NULL COMMENT '流行病学史',
  `qtjc` varchar(255) DEFAULT NULL COMMENT '其他检查',
  `clqk` varchar(255) DEFAULT NULL COMMENT '处理情况',
  `gthjkjy` varchar(255) DEFAULT NULL COMMENT '个体化健康教育',
  `breathe` varchar(255) DEFAULT NULL COMMENT '呼吸',
  `pulse` varchar(255) DEFAULT NULL COMMENT '脉搏',
  `blood_pressure` varchar(255) DEFAULT NULL COMMENT '血压',
  `temperature` varchar(255) DEFAULT NULL COMMENT '体温',
  `china_diagnose` varchar(255) DEFAULT NULL COMMENT '中医诊断',
  `western_diagnose` varchar(255) DEFAULT NULL COMMENT '西医诊断',
  `del_flag` varchar(32) NOT NULL DEFAULT '0' COMMENT '删除标记;（0：正常；1：删除）',
  `CREATED_BY` varchar(32) NOT NULL COMMENT '创建人',
  `CREATED_TIME` datetime NOT NULL COMMENT '创建时间',
  `UPDATED_BY` varchar(32) DEFAULT NULL COMMENT '更新人',
  `UPDATED_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `CREATED_ID` varchar(32) NOT NULL COMMENT '创建人ID',
  PRIMARY KEY (`mbbm`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='病历模板管理';
/*!40101 SET character_set_client = @saved_cs_client */;

