--
-- Table structure for table `clinic`
--

DROP TABLE IF EXISTS `clinic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `clinic` (
  `id` bigint(20) NOT NULL COMMENT '诊所ID',
  `lessee_id` bigint(20) NOT NULL COMMENT '租户代码',
  `name` varchar(100) NOT NULL COMMENT '诊所名称',
  `address_province` varchar(10) DEFAULT NULL COMMENT '地址(省)',
  `address_city` varchar(10) DEFAULT NULL COMMENT '地址(市)',
  `address_region` varchar(10) DEFAULT NULL COMMENT '地址(区)',
  `address` varchar(100) DEFAULT NULL COMMENT '地址',
  `phone_number` varchar(20) NOT NULL COMMENT '联系电话',
  `license_subject` varchar(100) DEFAULT NULL COMMENT '执业许可科目',
  `file_id` bigint(21) DEFAULT NULL COMMENT '诊所许可证图片',
  `version_id` bigint(21) NOT NULL COMMENT '诊所功能版本ID',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '1营业 0 停业',
  `start_use_date` datetime DEFAULT NULL COMMENT '启用时间',
  `expire_date` datetime DEFAULT NULL COMMENT '诊所到期时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `del_flag` char(1) DEFAULT NULL COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `FK_Reference_14` (`lessee_id`) USING BTREE,
  CONSTRAINT `FK_Reference_14` FOREIGN KEY (`lessee_id`) REFERENCES `lessee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='诊所';
/*!40101 SET character_set_client = @saved_cs_client */;

