--
-- Table structure for table `gen_table_column`
--

DROP TABLE IF EXISTS `gen_table_column`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `gen_table_column` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `gen_table_id` bigint(21) unsigned NOT NULL COMMENT '业务表',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `comments` varchar(64) NOT NULL COMMENT '描述',
  `jdbc_type` varchar(64) NOT NULL COMMENT '列字段类型',
  `java_type` varchar(64) NOT NULL COMMENT 'JAVA类型',
  `custom_type` varchar(64) DEFAULT NULL COMMENT '自定义类型',
  `java_field` varchar(512) NOT NULL COMMENT 'JAVA属性名',
  `def_val` varchar(2048) DEFAULT '' COMMENT '默认值',
  `is_pk` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否主键',
  `is_null` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否可为空',
  `is_insert` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否可插入',
  `is_edit` varchar(2) NOT NULL DEFAULT '0' COMMENT '是否可编辑',
  `is_list` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否列显',
  `width` int(11) NOT NULL COMMENT '列宽',
  `is_query` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否查询字段',
  `query_type` varchar(64) DEFAULT NULL COMMENT '查询方式（等于、不等于、大于、小于、范围、左LIKE、右LIKE、左右LIKE）',
  `query_val` varchar(2048) DEFAULT '' COMMENT '查询条件',
  `show_type` varchar(64) DEFAULT NULL COMMENT '控件',
  `interaction` varchar(2048) DEFAULT NULL COMMENT '联动变量',
  `interaction_val` varchar(2048) DEFAULT NULL COMMENT '联动值',
  `parameters` varchar(2048) DEFAULT NULL COMMENT '联动参数',
  `settings` varchar(2048) DEFAULT NULL COMMENT '其它设置（扩展字段JSON）',
  `sort` bigint(21) unsigned DEFAULT '0' COMMENT '排序',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `gen_table_id` (`gen_table_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='业务表字段';
/*!40101 SET character_set_client = @saved_cs_client */;

