--
-- Table structure for table `manufacture_factory`
--

DROP TABLE IF EXISTS `manufacture_factory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `manufacture_factory` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` varchar(45) DEFAULT NULL COMMENT '诊所id',
  `name` varchar(128) NOT NULL COMMENT '厂家名称',
  `people` varchar(45) DEFAULT NULL COMMENT '联系人',
  `phone` varchar(45) DEFAULT NULL COMMENT '电话',
  `province` varchar(45) DEFAULT NULL COMMENT '省',
  `city` varchar(45) DEFAULT NULL COMMENT '市',
  `area` varchar(45) DEFAULT NULL COMMENT '区',
  `address` varchar(128) DEFAULT NULL COMMENT '地址',
  `status` varchar(1) DEFAULT NULL COMMENT '启用标记',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `type` varchar(1) NOT NULL COMMENT '厂家类型',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='生产厂家';
/*!40101 SET character_set_client = @saved_cs_client */;

