--
-- Table structure for table `medical_record`
--

DROP TABLE IF EXISTS `medical_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `medical_record` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` bigint(21) NOT NULL COMMENT '诊所id',
  `doctor_id` bigint(21) NOT NULL COMMENT '医生id',
  `registration_id` bigint(21) NOT NULL COMMENT '挂号id',
  `patient_tell` varchar(128) NOT NULL COMMENT '主诉',
  `now_history` varchar(128) DEFAULT NULL COMMENT '现病史',
  `before_history` varchar(128) DEFAULT NULL COMMENT '既往史',
  `diagnose` varchar(128) DEFAULT NULL COMMENT '诊断',
  `personal_history` varchar(128) DEFAULT NULL COMMENT '个人史',
  `allergy_history` varchar(128) DEFAULT NULL COMMENT '过敏史',
  `disease_history` varchar(128) DEFAULT NULL COMMENT '疾病史',
  `pregnancy_history` varchar(128) DEFAULT NULL COMMENT '婚孕史',
  `infectious_history` varchar(128) DEFAULT NULL COMMENT '传染病史',
  `lunaria_history` varchar(128) DEFAULT NULL COMMENT '月经史',
  `family_history` varchar(128) DEFAULT NULL COMMENT '家族史',
  `surgery_history` varchar(128) DEFAULT NULL COMMENT '手术史',
  `transfusion_history` varchar(128) DEFAULT NULL COMMENT '输血史',
  `physique_check` varchar(128) DEFAULT NULL COMMENT '体格检查',
  `assist_check` varchar(128) DEFAULT NULL COMMENT '辅助检查',
  `emergency_diagnose` varchar(128) DEFAULT NULL COMMENT '急诊诊断',
  `emergency_effect` varchar(128) DEFAULT NULL COMMENT '急诊效果',
  `epidemic_disease` varchar(128) DEFAULT NULL COMMENT '流行病学史',
  `other_check` varchar(128) DEFAULT NULL COMMENT '其他检查',
  `handling_situation` varchar(128) DEFAULT NULL COMMENT '处理情况',
  `health_education` varchar(128) DEFAULT NULL COMMENT '个体化健康教育',
  `diagnose_date` datetime DEFAULT NULL COMMENT '诊断时间',
  `doctor_advice` varchar(128) DEFAULT NULL COMMENT '医嘱事项',
  `fee` decimal(10,0) DEFAULT NULL COMMENT '总费用',
  `file_id` varchar(45) DEFAULT NULL COMMENT '上传附件',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `western_diagnose` varchar(100) DEFAULT NULL COMMENT '西医诊断',
  `china_diagnose` varchar(100) DEFAULT NULL COMMENT '中医诊断',
  `department` varchar(255) DEFAULT NULL COMMENT '远程诊疗科室',
  `medic` varchar(255) DEFAULT NULL COMMENT '远程诊疗医生',
  `disease_id` varchar(100) DEFAULT NULL COMMENT '诊断id',
  `syndrome_id` varchar(100) DEFAULT NULL COMMENT '证候id',
  `china_syndrome` varchar(100) DEFAULT NULL COMMENT '中医证候',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='病历表';
/*!40101 SET character_set_client = @saved_cs_client */;

