CREATE TABLE `org_company` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `parent_id` bigint(21) unsigned DEFAULT NULL COMMENT '父级',
  `fixmedins_code` varchar(12) DEFAULT NULL COMMENT '定点医疗机构编码',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `full_name` varchar(512) DEFAULT NULL COMMENT '全称',
  `ids` varchar(2048) NOT NULL COMMENT '全标识',
  `code` varchar(64) DEFAULT NULL COMMENT '编码',
  `sort` bigint(21) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `address_province` varchar(10) NOT NULL COMMENT '地址（省）',
  `address_city` varchar(10) NOT NULL COMMENT '地址（市）',
  `address_region` varchar(10) NOT NULL COMMENT '地址（区）',
  `address` varchar(100) NOT NULL COMMENT '地址',
  `contact_name` varchar(100) DEFAULT NULL COMMENT '联系人姓名',
  `phone_number` varchar(21) NOT NULL COMMENT '电话号码',
  `license_subject` varchar(100) DEFAULT NULL COMMENT '执业许可科目',
  `file_id` bigint(21) unsigned DEFAULT NULL COMMENT '诊所许可证图片',
  `version_id` bigint(21) DEFAULT NULL COMMENT '诊所功能版本ID',
