  `fixmedins_name` varchar(100) DEFAULT NULL COMMENT '定点医疗机构名称',
  `uscc` varchar(100) DEFAULT NULL COMMENT '统一社会信用代码',
  `fixmedins_type` varchar(100) DEFAULT NULL COMMENT '定点医疗服务机构类型',
  `hosp_lv` varchar(100) DEFAULT NULL COMMENT '医院等级',
