--
-- Table structure for table `recipel_info`
--

DROP TABLE IF EXISTS `recipel_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `recipel_info` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `code` varchar(100) DEFAULT NULL COMMENT '处方编号',
  `name` varchar(100) DEFAULT NULL COMMENT '处方名称',
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `registration_id` bigint(20) DEFAULT NULL COMMENT '登记信息',
  `medical_record_id` bigint(21) DEFAULT NULL COMMENT '病历id',
  `recipel_type` varchar(64) DEFAULT NULL COMMENT '处方类别',
  `dosage` varchar(45) DEFAULT NULL COMMENT '剂量',
  `recipel_use` varchar(64) DEFAULT NULL COMMENT '用法',
  `frequency` varchar(64) DEFAULT NULL COMMENT '频次用量',
  `take_frequency` varchar(64) DEFAULT NULL COMMENT '服用频次',
  `single_dosage` int(11) DEFAULT NULL COMMENT '单次用量',
  `fee` decimal(10,2) DEFAULT NULL COMMENT '处方总价',
  `is_pay` varchar(1) DEFAULT '0' COMMENT '是否付款',
