--
-- Table structure for table `registration`
--

DROP TABLE IF EXISTS `registration`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `registration` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `department_id` bigint(21) DEFAULT NULL COMMENT '科室id',
  `patient_id` bigint(21) DEFAULT NULL COMMENT '患者id',
  `doctor_id` bigint(21) DEFAULT NULL COMMENT '医生id',
  `morbidity_time` datetime DEFAULT NULL COMMENT '发病时间',
  `treat_type` varchar(64) DEFAULT NULL COMMENT '治疗类型',
  `infect_type` varchar(64) DEFAULT NULL COMMENT '传染病',
  `source` varchar(64) DEFAULT NULL COMMENT '来源',
  `reception_start_date` datetime DEFAULT NULL COMMENT '接诊开始时间',
  `reception_end_date` datetime DEFAULT NULL COMMENT '接诊结束时间',
  `pulse` varchar(45) DEFAULT NULL COMMENT '脉搏',
  `breathe` varchar(45) DEFAULT NULL COMMENT '呼吸',
  `temperature` varchar(45) DEFAULT NULL COMMENT '体温',
  `is_go_higharea` varchar(64) DEFAULT '0' COMMENT '是否去过疫区',
  `high_area` varchar(128) DEFAULT NULL COMMENT '疫区地点',
  `free_registration_fee` varchar(64) DEFAULT '0' COMMENT '免挂号费',
  `registration_fee` decimal(10,2) DEFAULT NULL COMMENT '挂号费',
  `pay_type` varchar(64) DEFAULT NULL COMMENT '支付方式',
  `status` varchar(64) DEFAULT NULL COMMENT '状态',
  `dispensing_status` varchar(1) DEFAULT '0' COMMENT '发药状态',
  `dispensing_date` datetime DEFAULT NULL COMMENT '发/退药时间',
  `charge_status` varchar(1) DEFAULT '0' COMMENT '收费状态  0- 待收费   1-部分收费   2- 已收费   3-  部分退费    4- 已退费',
  `charge_date` datetime DEFAULT NULL COMMENT '收费时间',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `refund_registration_pay_type` varchar(64) DEFAULT NULL COMMENT '退挂号费支付方式',
  `refund_registration_remarks` varchar(255) DEFAULT NULL COMMENT '退挂号费备注',
  `practicle_registration_fee` decimal(10,4) DEFAULT NULL COMMENT '实际支付费用',
  `practicle_registration_pay_remarks` varchar(255) DEFAULT NULL COMMENT '实际支付备注',
  `pay_date` datetime DEFAULT NULL COMMENT '挂号登记支付时间',
  `signed_date` datetime DEFAULT NULL COMMENT '签到时间',
  `exit_number_date` datetime DEFAULT NULL COMMENT '退号时间',
  `follow_up_date` datetime DEFAULT NULL COMMENT '复诊时间',
  `guardian_name` varchar(64) DEFAULT NULL COMMENT '监护人姓名',
  `guardian_phone` varchar(64) DEFAULT NULL COMMENT '监护人电话',
  `workplace` varchar(255) DEFAULT NULL COMMENT '工作单位',
  `nation` varchar(255) DEFAULT NULL COMMENT '民族',
  `occupation` varchar(255) DEFAULT NULL COMMENT '职业',
  `recipe_status` varchar(1) DEFAULT '0' COMMENT '所有处方作废标记',
  `blood_pressure` varchar(100) DEFAULT NULL COMMENT '血压',
  `subscribe_date` datetime DEFAULT NULL COMMENT '预约时间',
  `subscribe_project` varchar(255) DEFAULT NULL COMMENT '预约项目',
  `retreats_date` datetime DEFAULT NULL COMMENT '退费时间',
  `return_date` datetime DEFAULT NULL COMMENT '退药时间',
  `treatment_date` datetime DEFAULT NULL COMMENT '诊疗完成时间',
  `overlook` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否忽略（0：否，1：是）',
  `mdtrt_id` varchar(30) DEFAULT NULL COMMENT '医保就诊id',
  `med_type` varchar(10) DEFAULT NULL COMMENT '医疗类别',
  `ipt_otp_no` varchar(100) DEFAULT NULL COMMENT '医保院内门诊号',
  `setl_id` varchar(64) DEFAULT NULL COMMENT '医保结算id',
  `card_type` varchar(10) DEFAULT NULL COMMENT '就诊凭证类型',
  `is_pre` varchar(10) DEFAULT NULL COMMENT '单电子处方标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='挂号表';
/*!40101 SET character_set_client = @saved_cs_client */;

