--
-- Table structure for table `remote_diagnosis`
--

DROP TABLE IF EXISTS `remote_diagnosis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `remote_diagnosis` (
  `id` varchar(21) NOT NULL COMMENT '主键',
  `company_id` varchar(45) DEFAULT NULL COMMENT '诊所id',
  `registration_id` varchar(255) DEFAULT NULL COMMENT '挂号id',
  `patient_id` varchar(255) DEFAULT NULL COMMENT '患者id',
  `hospital_id` varchar(255) DEFAULT NULL COMMENT '申请医院id',
  `department_id` varchar(255) DEFAULT NULL COMMENT '申请科室id',
  `medic_id` varchar(255) DEFAULT NULL COMMENT '申请医生id',
  `name` varchar(255) DEFAULT NULL COMMENT '患者姓名',
  `gender` varchar(255) DEFAULT NULL COMMENT '患者性别',
  `card` varchar(255) DEFAULT NULL COMMENT '身份证号',
  `hospital` varchar(255) DEFAULT NULL COMMENT '申请医院',
  `department` varchar(255) DEFAULT NULL COMMENT '申请科室',
  `medic` varchar(255) DEFAULT NULL COMMENT '申请医生',
  `diagnosis_time` datetime DEFAULT NULL COMMENT '诊疗时间',
  `application_results` varchar(255) DEFAULT NULL COMMENT '申请结果',
