DROP TABLE IF EXISTS `sys_action_recycle`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_action_recycle` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `action_id` bigint(21) unsigned NOT NULL COMMENT '日志',
  `table_name` varchar(128) NOT NULL COMMENT '表名',
  `object_id` bigint(21) unsigned NOT NULL COMMENT '业务对象',
  `object_name` varchar(128) DEFAULT NULL COMMENT '对象名称',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `action_id` (`action_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='回收站';
