  `sys_rule_id` bigint(21) unsigned NOT NULL COMMENT '系统编号规则',
  `code` varchar(64) NOT NULL COMMENT '编号',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `rule_def` varchar(512) NOT NULL COMMENT '规则',
