--
-- Table structure for table `sys_condition`
--

DROP TABLE IF EXISTS `sys_condition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_condition` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `user_id` bigint(21) unsigned NOT NULL COMMENT '用户Id',
  `router_id` bigint(21) unsigned NOT NULL COMMENT '路由Id',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `conditions` text NOT NULL COMMENT '条件',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `router_id` (`router_id`) USING BTREE,
  KEY `sys_condition_user_router` (`router_id`,`user_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='查询条件';
/*!40101 SET character_set_client = @saved_cs_client */;

